def min_stack(operations):
    stack, out = [], []
    for op in operations:
        if op[0] == 'push':
            value = op[1]
            stack.append((value, min(value,stack[-1][1]) if stack else value))
            out.append(None)
        elif op[0] == 'pop': out.append(stack.pop()[0] if stack else None)
        else: out.append(stack[-1][1] if stack else None)
    return out
